insert into public.astrofly_drones
  (id, slug, name, tagline, description, status, category, image, weight, flight_time, camera, video, range, sensing, best_for, sort_order)
values
  ('dji-mini-4k', 'dji-mini-4k', 'DJI Mini 4K', 'Light, steady and ready for most events.', 'Our everyday event drone. Under 250 grams, quiet enough for a church compound and steady in a breeze. It shoots clean 4K video and sharp stills, which covers most weddings, birthdays and outdoor programmes.', 'available', 'compact', '/drones/dji-mini-4k.webp', '249 g', '31 min', '1/2.3 inch CMOS, 12 MP', '4K at 30 fps', 'Up to 10 km', 'Downward vision', array['Weddings','Birthdays','Church programmes','Real estate']::text[], 1),
  ('dji-lito-1', 'dji-lito-1', 'DJI Lito 1', 'Brighter lens, longer flights, sensors all round.', 'A newer compact with a larger sensor and an f/1.8 lens, so evening receptions and indoor halls come out cleaner. Obstacle sensing on every side lets us fly closer to the crowd with more confidence.', 'available', 'compact', '/drones/dji-lito-1.webp', '249 g', '36 min', '1/2 inch CMOS, 48 MP, f/1.8', '4K up to 100 fps', 'Up to 15 km', 'Omnidirectional vision', array['Evening receptions','Concerts','Corporate launches','Sports']::text[], 2),
  ('dji-lito-x1', 'dji-lito-x1', 'DJI Lito X1', 'Bigger sensor and LiDAR for tight spaces.', 'A 1/1.3 inch sensor with forward LiDAR. Strong low light performance for night events and slow motion up to 200 fps in Full HD.', 'coming_soon', 'compact', '/drones/dji-lito-x1.webp', '249 g', '36 min', '1/1.3 inch CMOS, 48 MP, f/1.7', '4K at 60 fps, 100 fps slow motion', 'Up to 15 km', 'Omnidirectional vision with forward LiDAR', array['Night events','Concerts','Weddings']::text[], 3),
  ('dji-mini-4-pro', 'dji-mini-4-pro', 'DJI Mini 4 Pro', 'Pro image quality in a mini body.', 'True vertical shooting for reels, 4K HDR and full obstacle sensing. A favourite for social media heavy events.', 'coming_soon', 'compact', '/drones/dji-mini-4-pro.webp', '249 g', '34 min', '1/1.3 inch CMOS, 48 MP', '4K at 60 fps HDR, 100 fps slow motion', 'Up to 20 km', 'Omnidirectional vision', array['Social media reels','Weddings','Birthdays']::text[], 4),
  ('dji-mini-5-pro', 'dji-mini-5-pro', 'DJI Mini 5 Pro', 'A 1 inch sensor that still weighs under 250 g.', 'The biggest sensor DJI has put in a mini drone. Rich colour, deep shadows and 4K slow motion up to 120 fps.', 'coming_soon', 'pro', '/drones/dji-mini-5-pro.webp', '249.9 g', '36 min', '1 inch CMOS, 50 MP', '4K up to 120 fps', 'Up to 20 km', 'Omnidirectional vision with forward LiDAR', array['Weddings','Real estate','Corporate launches']::text[], 5),
  ('dji-air-3s', 'dji-air-3s', 'DJI Air 3S', 'Two cameras for wide and close shots in one flight.', 'A 1 inch main camera plus a 70 mm medium tele. We can take the full venue and then push in on the couple without landing.', 'coming_soon', 'pro', '/drones/dji-air-3s.webp', '724 g', '45 min', '1 inch CMOS 50 MP plus 70 mm tele 48 MP', '4K at 60 fps HDR', 'Up to 20 km', 'Omnidirectional vision with forward LiDAR', array['Large weddings','Real estate','Sports']::text[], 6),
  ('dji-mavic-4-pro', 'dji-mavic-4-pro', 'DJI Mavic 4 Pro', 'Hasselblad colour and three cameras.', 'A 4/3 Hasselblad main camera, two tele lenses and a gimbal that rotates all the way round. For premium productions and brand films.', 'coming_soon', 'cinema', '/drones/dji-mavic-4-pro.webp', '1063 g', '51 min', '4/3 CMOS Hasselblad, 100 MP', '6K at 60 fps HDR', 'Up to 30 km', 'Omnidirectional vision', array['Brand films','Real estate','Corporate launches']::text[], 7),
  ('dji-avata-2', 'dji-avata-2', 'DJI Avata 2', 'Fly through the hall, over the dance floor.', 'An FPV drone with guarded propellers for indoor fly throughs and dramatic one take shots.', 'coming_soon', 'fpv', '/drones/dji-avata-2.webp', '377 g', '23 min', '1/1.3 inch CMOS, 12 MP', '4K at 60 fps, 155 degree view', 'Up to 13 km', 'Downward and backward vision', array['Indoor fly throughs','Concerts','Launches']::text[], 8),
  ('dji-avata-360', 'dji-avata-360', 'DJI Avata 360', 'Shoot everything, frame it later.', 'Two 1/1.1 inch sensors record 8K 360 video, so every angle of the moment is captured and reframed in the edit.', 'coming_soon', 'fpv', '/drones/dji-avata-360.webp', '455 g', '23 min', 'Dual 1/1.1 inch CMOS, 64 MP', '8K 360 at 60 fps', 'Up to 20 km', 'Omnidirectional vision with forward LiDAR', array['Concerts','Sports','Immersive reels']::text[], 9),
  ('dji-flip', 'dji-flip', 'DJI Flip', 'Full prop guards for close, safe vlog shots.', 'Foldable with full propeller guards. Great for close shots around guests and quick social clips.', 'coming_soon', 'selfie', '/drones/dji-flip.webp', '249 g', '31 min', '1/1.3 inch CMOS, 48 MP', '4K at 60 fps HDR', 'Up to 13 km', 'Forward 3D infrared sensing', array['Birthdays','Social media reels','Small gatherings']::text[], 10),
  ('dji-neo-2', 'dji-neo-2', 'DJI Neo 2', 'Palm sized follow shots.', 'Takes off from the palm and follows the subject. Fun for entrances, dance moments and quick reels.', 'coming_soon', 'selfie', '/drones/dji-neo-2.webp', '151 g', '19 min', '1/2 inch CMOS', '4K at 60 fps', 'Up to 10 km', 'Omnidirectional vision with forward LiDAR', array['Entrances','Dance moments','Reels']::text[], 11),
  ('dji-inspire-3', 'dji-inspire-3', 'DJI Inspire 3', 'Full frame 8K cinema from the sky.', 'A professional cinema platform with a full frame 8K camera. For film sets, music videos and big budget productions.', 'coming_soon', 'cinema', '/drones/dji-inspire-3.webp', '3995 g', '28 min', 'Full frame Zenmuse X9 8K Air', '8K at 75 fps', 'Up to 15 km', 'Omnidirectional vision', array['Music videos','Films','Large concerts']::text[], 12)
